:root {
  --paper: #fffaf1;
  --ink: #3d2d22;
  --muted: #856f5d;
  --crust: #b85d35;
  --peach: #f5d5ad;
}

.order-card {
  width: 440px;
  padding: 16px;
  background: var(--paper);
  border: 2px solid var(--ink);
  border-radius: 16px;
  color: var(--ink);
}

.order-header,
.order-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.eyebrow {
  margin: 0;
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1px;
}

.status {
  padding: 5px 9px;
  background: var(--peach);
  border-radius: 999px;
  color: var(--crust);
  font-size: 12px;
  font-weight: 700;
}

.order-body {
  margin: 12px 0;
  padding: 12px 0;
  border-top: 1px solid var(--peach);
  border-bottom: 1px solid var(--peach);
}

.order-body h1 {
  margin: 0 0 4px;
  font-size: 21px;
  line-height: 1.15;
}

.order-body p {
  margin: 0;
  color: var(--muted);
  font-size: 14px;
  line-height: 1.35;
}

.order-footer strong {
  font-size: 18px;
}

.order-footer button {
  padding: 8px 12px;
  border: 0;
  border-radius: 8px;
  background: var(--crust);
  color: var(--paper);
  font-size: 13px;
  font-weight: 700;
}
